def build_guide(topic, record):
    definition, intuition, process, example, vocabulary, mistake, application = record
    steps = process.split('|')
    question, answer, explanation = application.split('|')
    terms = vocabulary.split('; ')
    return {
        'definition': definition,
        'intuitive_explanation': intuition,
        'step_by_step': '\n\n'.join(f'{i}. {step}' for i, step in enumerate(steps, 1)),
        'example': example,
        'calculation': 'Worked case above: state the assumptions and show each intermediate result. Numerical cases use explicitly stated toy data.',
        'diagram': ' -> '.join(steps[:3]),
        'terminology': terms,
        'common_mistakes': mistake,
        'exam_tip': f'Define {topic}, explain {terms[0]}, show the worked case, and discuss the specific limitation below. Mark allocations are illustrative.',
        'revision': f'{definition} Key terms: {vocabulary}. Remember: {mistake}',
        'practice_questions': [
            {'question': f'Define {topic}.', 'answer': definition, 'explanation': intuition},
            {'question': question, 'answer': answer, 'explanation': explanation},
            {'question': f'Explain one misconception about {topic}.', 'answer': mistake, 'explanation': f'Use this case to support your explanation: {example}'},
        ],
        'model_answer_5': f'**Definition (1 mark)**\n\n{definition}\n\n**Method / key points (2 marks)**\n\n' + ' '.join(steps) + f'\n\n**Example (1 mark)**\n\n{example}\n\n**Limitation (1 mark)**\n\n{mistake}',
        'model_answer_10': f'**Definition and intuition (2 marks)**\n\n{definition} {intuition}\n\n**Technical explanation (4 marks)**\n\n' + '\n\n'.join(f'{i}. {step}' for i, step in enumerate(steps, 1)) + f'\n\nRelevant terms: {vocabulary}.\n\n**Worked illustration (2 marks)**\n\n{example}\n\n**Discussion and limitation (2 marks)**\n\n{explanation} {mistake}',
    }
